import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const h=JSON.parse('{"title":"Commercial go-live acceptance","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/go-live-checklist.md","filePath":"getting-started/go-live-checklist.md"}'),n={name:"getting-started/go-live-checklist.md"};function o(c,e,d,s,l,p){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="commercial-go-live-acceptance" tabindex="-1">Commercial go-live acceptance <a class="header-anchor" href="#commercial-go-live-acceptance" aria-label="Permalink to &quot;Commercial go-live acceptance&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Reference release</p><p>Operational guidance reviewed against v0.7.26. Verify the installed release, permissions and approved scope. Training uses authorized synthetic data; this guide does not authorize commercial activation.</p></div><h2 id="acceptance-record" tabindex="-1">Acceptance record <a class="header-anchor" href="#acceptance-record" aria-label="Permalink to &quot;Acceptance record&quot;">​</a></h2><p>Record company, approved environment, exact release, review date, business owner, technical owner and scope. Use the checklist as a manual record; marking a box in documentation does not activate a feature.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Required evidence</th></tr></thead><tbody><tr><td>Installation</td><td>Approved release and signature, HTTPS, health, migrations and restore-tested backups</td></tr><tr><td>Access</td><td>Actual administrator, dispatcher, driver and viewer accounts; isolation and denied actions</td></tr><tr><td>Company data</td><td>Approved company, markets, locations, fleet, driver availability, taxes and tariffs</td></tr><tr><td>Booking</td><td>Four supported service modes where sold, phone-only booking, manual quote, duplicate and conflict protection</td></tr><tr><td>Dispatch</td><td>Full-duration checks, vehicle maintenance, independent legs and arrival-advisory review</td></tr><tr><td>Finance</td><td>Cash collection, custody and reconciliation; approved payment provider acceptance only if enabled</td></tr><tr><td>Public gateway</td><td>Domain/channel isolation, verified quotes, abuse prevention and explicit public-intake approval</td></tr><tr><td>Messaging and AI</td><td>Privacy, consent, opt-out, verified delivery, human takeover and provider authorization</td></tr><tr><td>GPS and regulatory</td><td>Physical mobile testing and separately approved live integration; sandbox is not compliance</td></tr><tr><td>Operations</td><td>Staff training, support, incident fallback and owner sign-off</td></tr></tbody></table><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Mark each gate passed, failed or not applicable with evidence and responsible owner. Defer affected workflows until accepted. No blanket commercial go-live claim follows from a signed release, complete onboarding checklist, successful CI or passing documentation checks.</p><p>The v0.7.26 release leaves automated external arrivals, background scheduling, complete provider quota enforcement, licensed street-map configuration and physical mobile GPS acceptance outstanding. External providers and public intake remain disabled pending authorization. Live regulatory submissions require separate acceptance. Customer production installation is not asserted.</p><p>See <a href="/installation/">Installation</a>, <a href="/getting-started/backup-recovery.html">Backup and recovery</a> and <a href="/integrations/third-party-api-setup.html">Third-party setup</a>.</p>',9)])])}const m=t(n,[["render",o]]);export{h as __pageData,m as default};
